.elementor-1271 .ja-preview{max-width:none;margin:0;padding:24px 0 0}
.elementor-1271 .ja-preview{--ja-navy:#122e43;--ja-ink:#223747;--ja-blue:#236b9c;--ja-sky:#86cef7;--ja-muted:#657783;--ja-line:#e1eaf0;--ja-paper:#f4f8fb;--ja-radius:12px;--ja-max:1350px;--ja-gutter:20px;color:var(--ja-ink);background:white;font-family:'Segoe UI','Nirmala UI','Noto Sans Bengali',Arial,sans-serif;line-height:1.85;-webkit-font-smoothing:antialiased}
