.elementor-1271 .ja-preview img{display:block;max-width:100%;width:100%;object-fit:cover}
.elementor-1271 .ja-preview svg{flex-shrink:0}
.elementor-1271 .ja-preview h1,.elementor-1271 .ja-preview h2,.elementor-1271 .ja-preview h3,.elementor-1271 .ja-preview p,.elementor-1271 .ja-preview figure,.elementor-1271 .ja-preview blockquote{margin:0;padding:0;font-family:inherit;color:inherit}
.elementor-1271 .ja-preview h1,.elementor-1271 .ja-preview h2,.elementor-1271 .ja-preview h3{text-wrap:balance}
