.elementor-1271 .ja-preview .ja-section{padding-block:88px}
.elementor-1271 .ja-preview .ja-eyebrow{display:flex;align-items:center;gap:10px;font-size:10px;font-weight:700;letter-spacing:2px;line-height:1.6;color:var(--ja-blue);margin-bottom:20px}
