.elementor-1271 .ja-preview .ja-eyebrow.ja-light{color:#b2dff9}
.elementor-1271 .ja-preview h2{font-size:clamp(28px,2.6vw,38px);font-weight:650;line-height:1.55;letter-spacing:-.35px;margin-bottom:20px}
.elementor-1271 .ja-preview p{font-size:15px;line-height:1.95;color:var(--ja-muted)}
.elementor-1271 .ja-preview .ja-button .elementor-button{display:inline-flex;align-items:center;justify-content:center;gap:24px;min-height:54px;padding:14px 22px;background:var(--ja-blue);color:white;font-size:14px;font-weight:600;line-height:1.6;transition:transform .2s,background .2s,box-shadow .2s}
